insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$nazare-paulista$q$, $q$https://www.nazarepaulista.sp.gov.br/legislacao/download-lei/4256/ (Lei 1.611/2021); https://www.nazarepaulista.sp.gov.br/legislacao/download-lei/1994/ (Lei 407/1997); https://www.nazarepaulista.sp.gov.br/legislacao/download-lei/2343/ (Lei 744/2008)$q$, $q$Ato oficial do município: domínio público (Lei 9.610/1998 art. 8º IV). Geometria derivada do OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 3, $q$Lei 1.611/2021: proibição só no sentido Rotatória Principal -> Centro; a camada de vias não modela sentido, então a Rua João de Passos vale nos dois sentidos (aproximação conservadora). Lei 407/97 (PBT > 9 t em todas as vias pavimentadas) e Lei 744/08 (Estrada Vicinal Túnel das Águas Claras) ficam desativadas.$q$);
